def _gen():
    return '900%06d' % random.randint(0, 999999)

def _plan_of(item, req_id):
    # 逐品 plan_json：优先取元素 payload（合并方案 JSON），注入 req_id 供后端提取方案key
    raw = item.get('plan_json') or item.get('payload') or item.get('product_config') or ''
