        return {}
    out = {}
    for i, o in enumerate(obj, start=1):
        if not isinstance(o, dict):
            continue
        seq = str(o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i)
        name = str(o.get('name') or '').strip()
        qty = o.get('quantity')
        if name or qty not in (None, ''):
            out[seq] = {'name': name, 'quantity': qty}
    return out

def _merge_roster(offers, raw):
    # 按 offer_seq 把权威名册的 name/quantity 合并进逐品元素（已有非空 name 不覆盖）
    roster = _roster_map(raw)
    if not roster or not isinstance(offers, list):
        return offers
    for i, o in enumerate(offers, start=1):
        if not isinstance(o, dict):
            continue
        seq = str(o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i)
        r = roster.get(seq)
        if not r:
            continue
        if r.get('name') and not str(o.get('name') or '').strip():
            o['name'] = r['name']
        if r.get('quantity') not in (None, '') and o.get('quantity') in (None, ''):
            o['quantity'] = r['quantity']
    return offers


def _load(text):
    if isinstance(text, list):
        return {'offers': text}
    if isinstance(text, dict):
        return text
    if not isinstance(text, str) or not text.strip():
        return {}
    try:
        obj = json.loads(text)
        if isinstance(obj, list):
            return {'offers': obj}
        return obj if isinstance(obj, dict) else {}
    except Exception:
        try:
            t = text.strip()
            if ':' in t and not t.startswith('{') and not t.startswith('['):
                t = t.split(':', 1)[1].strip()
            obj = json.loads(t)
            if isinstance(obj, list):
                return {'offers': obj}
            return obj if isinstance(obj, dict) else {}
        except Exception:
            return {}

def _cell(v):
    return str(v) if v not in (None, '') else '—'

def _name_of(cfg):
    plan = cfg.get('plan_json') if isinstance(cfg.get('plan_json'), dict) else {}
    base = plan.get('baseInfo') if isinstance(plan.get('baseInfo'), dict) else {}
    return str(base.get('prodPrcName') or cfg.get('offer_name') or '').strip()

def _summary_of(cfg):
    plan = cfg.get('plan_json') if isinstance(cfg.get('plan_json'), dict) else {}
    info = plan.get('optionalInfo') if isinstance(plan.get('optionalInfo'), dict) else {}
    print_c = info.get('printContent') if isinstance(info.get('printContent'), dict) else {}
    gprs = info.get('billGprsCfg') if isinstance(info.get('billGprsCfg'), dict) else {}
    voice = info.get('billVoiceCfg') if isinstance(info.get('billVoiceCfg'), dict) else {}
    base = plan.get('baseInfo') if isinstance(plan.get('baseInfo'), dict) else {}
    in_fee = cfg.get('in_fee') if isinstance(cfg.get('in_fee'), dict) else {}
    offer_name = _name_of(cfg)
    fee = str(print_c.get('prcMonthFee') or base.get('fixFee') or '').strip()
    gift = str(print_c.get('containResource') or '').strip()
    if not gift:
        parts = []
        if str(gprs.get('theshold') or '').strip():
            parts.append('国内通用流量 %s%s' % (gprs.get('theshold'), gprs.get('unit') or ''))
        if str(voice.get('theshold') or '').strip():
            parts.append('国内通话 %s分钟' % voice.get('theshold'))
        gift = '、'.join(parts)
    out_price = str(print_c.get('chargeStandard') or '').strip()
    if not out_price:
        parts = []
        if str(gprs.get('outChargeMode') or '').strip():
            parts.append('套外流量 %s' % gprs.get('outChargeMode'))
        if str(voice.get('outCharge') or '').strip():
            parts.append('套外语音 %s元/分钟' % voice.get('outCharge'))
        out_price = '、'.join(parts)
    cycle = str(in_fee.get('计费周期') or '').strip()
    carry = '是' if str(gprs.get('carryFlag') or '').strip() in ('是', 'true', 'True', '1') else ''
    lines = ['- 销售品名称：%s' % _cell(offer_name)]
    lines.append('- 套餐档位（月费）：%s' % ((fee + ' 元/月') if fee else '—'))
    lines.append('- 套内资源：%s' % _cell(gift))
    lines.append('- 套外资费：%s' % _cell(out_price))
    if cycle:
        lines.append('- 计费周期：%s' % cycle)
    if carry:
        lines.append('- 流量结转：可结转至次月')
    lines.append('- 订购规则：%s' % _cell(cfg.get('order_rule')))
    lines.append('- 退订规则：%s' % _cell(cfg.get('cancel_rule')))
    return '\n'.join(lines)

def _save_result_one(cfg):
    sr = cfg.get('save_result')
    if isinstance(sr, str):
        sr = _load(sr)
        sr = sr if isinstance(sr, list) else []
    if not isinstance(sr, list):
        sr = []
    items = []
    for x in sr:
        if not isinstance(x, dict):
            continue
        cat = str(x.get('category') or '').strip()
        res = str(x.get('result') or '').strip()
        if cat:
            items.append((cat, res or '—'))
    if not items:
        return '无'
    if all(res.lower() == 'success' for _, res in items):
        return '全部成功'
    bad = ['%s=%s' % (cat, res) for cat, res in items if res.lower() != 'success']
    return '；'.join(bad) if bad else '；'.join('%s=%s' % it for it in items)

def _indent(text, prefix):
    return '\n'.join(prefix + ln if ln else ln for ln in str(text).split('\n'))

def _inner_of(c):
    inner = c.get('product_config')
    if isinstance(inner, str):
        inner = _load(inner) or None
    elif not isinstance(inner, dict):
        inner = None
    return inner if inner is not None else c

def _report(offers):
    # 逐品聚合：每品一块，集中展示商品名/offer_id、四类写入结果、配置要点、脚本下载地址。
    blocks = []
    for i, c in enumerate(offers, start=1):
        if not isinstance(c, dict):
            continue
        seq = int(c.get('offer_seq') or i)
        inner = _inner_of(c)
        oid = str(inner.get('offer_id') or c.get('offer_id') or '').strip()
        name = _name_of(inner) or str(inner.get('offer_name') or '').strip() or '未命名商品'
        head = '【第%d档】%s' % (seq, name)
        if oid:
            head += '（offer_id %s）' % oid
        lines = [head]
        lines.append('· 写入结果：%s' % _save_result_one(c))
        lines.append('· 配置要点：')
        lines.append(_indent(_summary_of(inner), '  '))
        url = str(c.get('script_url') or '').strip()
        lines.append('· 脚本下载：%s' % (url or '暂不可用，见智能配置结果'))
        blocks.append('\n'.join(lines))
    return '\n\n'.join(blocks) if blocks else '无'

def _fusion_of(offers):
    # 逐品融合组概况：仅当存在融合组（元素 group.members 非空）时才输出，避免单品场景噪声。
    echoes, failed = [], []
    for i, c in enumerate(offers, start=1):
        if not isinstance(c, dict):
            continue
        merged = c.get('group') if isinstance(c.get('group'), dict) else None
        if not merged:
            continue
        seq = int(c.get('offer_seq') or i)
        members = merged.get('members') or []
        parts = []
        for m in members:
            role = str(m.get('role') or '').strip()
            oid = str(m.get('offer_id') or '').strip()
            if role:
                parts.append('%s（offer_id %s）' % (role, oid))
            ms = str(m.get('status') or '').strip().upper()
            if ms in ('PARTIAL', 'FAIL'):
                failed.append('第%d档 %s=%s' % (seq, role or oid, ms))
        if parts:
            main_id = str(merged.get('main_offer_id') or c.get('offer_id') or '').strip()
            line = '第%d档融合成员：' % seq
            if main_id:
                line += '主 offer_id %s / ' % main_id
            line += ' / '.join(parts)
            echoes.append(line)
    note = ''
    if failed:
        note = '融合组部分成功（%s）：请按失败明细说明修改意见或回复【重新执行】' % '、'.join(failed)
    return '\n'.join(echoes), note

def _headline(offers, fusion_echo, fusion_note):
    n = len([c for c in offers if isinstance(c, dict)]) if isinstance(offers, list) else 0
    if n <= 1:
        one = next((c for c in offers if isinstance(c, dict)), None) if isinstance(offers, list) else None
        name = ''
        oid = ''
        if one is not None:
            inner = _inner_of(one)
            name = _name_of(inner) or str(inner.get('offer_name') or '').strip()
            oid = str(inner.get('offer_id') or one.get('offer_id') or '').strip()
        label = name or oid or '—'
        head = '智能配置完成：%s' % label
        if name and oid:
            head += '（offer_id %s）' % oid
    else:
        head = '智能配置完成：共 %d 个商品' % n
    if fusion_echo:
        head += '\n' + fusion_echo
    if fusion_note:
        head += '\n' + fusion_note
    return head

def _status_display(status):
    # 空值回退：节点103 status 可能为空（如无方案/未落地），避免结束节点模板泄漏裸占位符
    st = str(status or '').strip().upper()
    if st == 'SUCCESS':
        return 'SUCCESS（全部成功）'
    if st == 'PARTIAL':
        return 'PARTIAL（部分成功）'
    if st == 'FAIL':
        return 'FAIL（全部失败）'
    return st or '未通过'

def _nextstep(status, offers):
    st = str(status or '').strip().upper()
    all_success = True
    for c in offers if isinstance(offers, list) else []:
        if not isinstance(c, dict):
            continue
        sr = c.get('save_result')
        if isinstance(sr, str):
            sr = _load(sr)
        if not isinstance(sr, list):
            continue
        for x in sr:
            if isinstance(x, dict) and str(x.get('result') or '').strip().lower() not in ('', 'success'):
                all_success = False
                break
    if st == 'SUCCESS' and all_success:
        return '【下一步】回复【下一步】继续发起【规格稽核】（环节4/8）。'
    return '【下一步】本次存在部分/失败项，请核对上述明细；确认无误后回复【下一步】继续发起【规格稽核】（环节4/8）。'

async def main(args):
    p = args.params
    cfg = _load(p.get('product_config') or '')
    req_id = str(p.get('req_id') or '')
    status = str(p.get('status') or '')
    # V3.12 多商品：product_config 为节点103出参 offers[]（含逐品 product_config）；
    # 组装 config_json={req_id, offers:[...]} 信封供下游 result_json 落库（下游按 offers[] 键提取）。
    if isinstance(cfg, dict) and isinstance(cfg.get('offers'), list):
        offers = cfg['offers']
        blocks, offers_out, cfg_offers = [], [], []
        for i, c in enumerate(offers, start=1):
            if not isinstance(c, dict):
                continue
            seq = int(c.get('offer_seq') or i)
            inner = _inner_of(c)
            text = _summary_of(inner)
            blocks.append('第%d档：%s\n%s' % (seq, _name_of(inner) or '未命名商品', text))
            offers_out.append({'offer_seq': seq, 'config_summary': text})
            cfg_offers.append(c)
        # V3.14：按权威名册（节点111 offers，含 name/quantity）合并销售品名称与数量，
        # 供 config 落库 offers[] 携带 name/quantity，保证下游文案一致（名册缺失时零变化）。
        cfg_offers = _merge_roster(cfg_offers, p.get('roster') or '')
        fusion_echo, fusion_note = _fusion_of(offers)
        config_json = json.dumps({'req_id': req_id, 'offers': cfg_offers}, ensure_ascii=False)
        ret: Output = {
            'config_summary': '\n\n'.join(blocks),
            'offers': json.dumps(offers_out, ensure_ascii=False),
            'config_json': config_json,
            'report': _report(offers),
            'headline': _headline(offers, fusion_echo, fusion_note),
            'nextstep': _nextstep(status, offers),
            'status_display': _status_display(status),
        }
        return ret
    if not cfg:
        ret: Output = {'config_summary': '', 'offers': '[]', 'config_json': json.dumps({'req_id': req_id, 'offers': []}, ensure_ascii=False), 'report': '无', 'headline': '智能配置完成：无可展示商品', 'nextstep': '【下一步】回复【下一步】继续发起【规格稽核】（环节4/8）。', 'status_display': _status_display(status)}
        return ret
    one_sum = _summary_of(cfg)
    ret: Output = {'config_summary': one_sum, 'offers': json.dumps([{'offer_seq': 1, 'config_summary': one_sum}], ensure_ascii=False), 'config_json': json.dumps({'req_id': req_id, 'offers': [cfg]}, ensure_ascii=False), 'report': _report([cfg]), 'headline': _headline([cfg], '', ''), 'nextstep': _nextstep(status, [cfg]), 'status_display': _status_display(status)}
    return ret

from typing import Any, Dict

def _csv(v):
    # offers 入参可能是 JSON 数组字符串或已归一数组，拍平为 offer_id 逗号串
    import json as _json
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return ''
        try:
            v = _json.loads(s)
        except Exception:
            v = s
    if isinstance(v, dict) and isinstance(v.get('offers'), list):
        v = v['offers']
    if not isinstance(v, list):
        return ''
    ids = []
    for o in v:
        oid = str((o or {}).get('offer_id') or '') if isinstance(o, dict) else ''
        if oid:
            ids.append(oid)
    return ','.join(ids)

async def main(args):
    p = args.params
    chat_id = str(p.get('chat_id') or '')
    offer_id = str(p.get('offer_id') or '')
    offer_name = str(p.get('offer_name') or '')
    req_id = str(p.get('req_id') or '')
    offers_csv = _csv(p.get('offers'))
